INSERT INTO t_order_refund_position (
    order_refund_position_id, order_id, refundable_base_amount, reserved_amount, refunded_amount,
    currency, version, create_time, update_time
) VALUES (
    #{orderRefundPositionId}, #{orderId}, #{refundableBaseAmount}, #{reservedAmount}, #{refundedAmount},
    #{currency}, #{version}, #{createTime}, #{updateTime}
)

mapper.update:
UPDATE t_order_refund_position
SET reserved_amount=reserved_amount+#{amount},version=version+1,update_time=#{now}
WHERE order_refund_position_id=#{position.orderRefundPositionId}
    AND order_id=#{order.orderId} AND version=#{position.version} AND currency=#{order.currency}
    AND refundable_base_amount=#{position.refundableBaseAmount}
    AND refundable_base_amount-reserved_amount-refunded_amount >= #{amount}
    AND EXISTS (
        SELECT 1 FROM t_commerce_order o
        JOIN t_order_payment_projection p ON p.order_id=o.order_id
        WHERE o.order_id=#{order.orderId} AND o.client_id=#{order.clientId} AND o.version=#{order.version}
            AND o.order_status='PAID' AND o.paid_at=#{order.paidAt}
            AND o.currency=#{order.currency} AND o.total_amount=#{order.totalAmount}
            AND p.order_payment_projection_id=#{payment.orderPaymentProjectionId}
            AND p.payment_intent_id=#{payment.paymentIntentId} AND p.version=#{payment.version}
            AND p.intent_status='SUCCEEDED' AND p.successful_attempt_id=#{payment.successfulAttemptId}
            AND p.currency=o.currency AND p.captured_amount=o.total_amount
            AND p.captured_amount=#{position.refundableBaseAmount}
    )

UPDATE t_order_refund_position SET refundable_base_amount=#{amount},version=version+1,update_time=#{now}
WHERE order_refund_position_id=#{position.orderRefundPositionId} AND order_id=#{position.orderId}
    AND version=#{position.version} AND currency=#{position.currency}
    AND refundable_base_amount=0 AND reserved_amount=0 AND refunded_amount=0

UPDATE t_order_refund_position SET reserved_amount=reserved_amount-#{amount},
    refunded_amount=refunded_amount+#{amount},
    version=version+1,update_time=#{now}
WHERE order_id=#{position.orderId} AND version=#{position.version} AND currency=#{position.currency}
    AND reserved_amount >= #{amount}
